const fs = require('fs');
const workerPath = '_worker.js';
let source = fs.readFileSync(workerPath, 'utf8');
const marker = '// bare-review-video-player-v1';
if (!source.includes(marker)) {
  source += `\n\n${marker}\nconst bareReviewVideoStyle='<style id="bare-review-video-style">.review-media:has(.bare-review-video-frame){display:block!important}.bare-review-video-frame{display:block!important;width:min(420px,100%)!important;height:auto!important;margin-top:4px!important;overflow:hidden!important;border:1px solid #d9d9d9!important;border-radius:6px!important;background:#050505!important}.bare-review-video{display:block!important;width:100%!important;height:auto!important;max-height:560px!important;aspect-ratio:9/16!important;object-fit:contain!important;background:#050505!important}@media(max-width:860px){.bare-review-video-frame{width:100%!important;max-width:360px!important}.bare-review-video{max-height:66svh!important}}</style>';\nconst bareReviewVideoScript='<script id="bare-review-video-script">(()=>{let timer=0;function sync(){document.querySelectorAll(".review-media img").forEach(img=>{const raw=img.getAttribute("src")||"";if(!/\\.(mp4|webm|mov)(?:[?#]|$)/i.test(raw))return;const old=img.closest("span,a")||img,parent=document.createElement("span"),video=document.createElement("video");parent.className="bare-review-video-frame";video.className="bare-review-video";video.controls=true;video.preload="metadata";video.playsInline=true;video.setAttribute("playsinline","");video.setAttribute("webkit-playsinline","");video.src=raw;const poster=raw.replace(/\\.(mp4|webm|mov)(?=([?#]|$))/i,".jpg");video.poster=poster;video.setAttribute("aria-label",(img.getAttribute("alt")||"상품 리뷰")+" 영상");parent.appendChild(video);old.replaceWith(parent)})}function queue(){clearTimeout(timer);timer=setTimeout(sync,60)}new MutationObserver(queue).observe(document.body,{childList:true,subtree:true});addEventListener("hashchange",queue);queue()})();<\\/script>';\nconst bareReviewVideoBase=patchHtml;\npatchHtml=function(html){return bareReviewVideoBase(html).replace('</head>',bareReviewVideoStyle+'</head>').replace('</body>',bareReviewVideoScript+'</body>')};\n`;
  fs.writeFileSync(workerPath, source);
}
for (const path of ['.github/add-review-video-player.cjs','.github/workflows/add-review-video-player.yml']) {
  if (fs.existsSync(path)) fs.unlinkSync(path);
}
